package com.nightbeam.sporeandstem.registry;

import com.nightbeam.sporeandstem.SporeAndStem;
import net.minecraft.core.registries.Registries;
import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.biome.Biome;
import net.minecraft.world.level.block.Block;

/** Tag keys. The tag files are generated by tools/assets. */
public final class ModTags {
    private ModTags() {
    }

    public static final class Blocks {
        /** Where small fungi survive in any light (dirt-like blocks, moss, mycelium, Mycelial Soil). */
        public static final TagKey<Block> FUNGUS_SOIL = tag("fungus_soil");
        /** Logs and stems Shelf Fungus can grow on. */
        public static final TagKey<Block> SHELF_FUNGUS_HOSTS = tag("shelf_fungus_hosts");
        /** Blocks a Fruiting Heart summons the Myceliarch from. */
        public static final TagKey<Block> MYCELIARCH_SUMMON_BLOCKS = tag("myceliarch_summon_blocks");
        /** Mined fast by the Foraging Knife. */
        public static final TagKey<Block> MINEABLE_WITH_KNIFE = tag("mineable/knife");
        /** Every small fungus block (ours and vanilla mushrooms). */
        public static final TagKey<Block> FUNGI = tag("fungi");
        public static final TagKey<Block> CAPS = tag("caps");
        public static final TagKey<Block> GLOWCAP_STEMS = tag("glowcap_stems");
        public static final TagKey<Block> BOUNCECAP_STEMS = tag("bouncecap_stems");
        public static final TagKey<Block> INKCAP_STEMS = tag("inkcap_stems");

        private static TagKey<Block> tag(String name) {
            return TagKey.create(Registries.BLOCK, SporeAndStem.id(name));
        }
    }

    public static final class Items {
        public static final TagKey<Item> FUNGI = tag("fungi");
        public static final TagKey<Item> EDIBLE_FUNGI = tag("edible_fungi");
        public static final TagKey<Item> CAPS = tag("caps");
        public static final TagKey<Item> GLOWCAP_STEMS = tag("glowcap_stems");
        public static final TagKey<Item> BOUNCECAP_STEMS = tag("bouncecap_stems");
        public static final TagKey<Item> INKCAP_STEMS = tag("inkcap_stems");
        /** Tools that harvest an extra fungus and Mycelial Thread (the Foraging Knife). */
        public static final TagKey<Item> FORAGING_TOOLS = tag("foraging_tools");

        private static TagKey<Item> tag(String name) {
            return TagKey.create(Registries.ITEM, SporeAndStem.id(name));
        }
    }

    public static final class Entities {
        /** Fungal creatures: immune to Mycosis and spore clouds. */
        public static final TagKey<EntityType<?>> FUNGAL = tag("fungal");
        /** Mobs that rise as Shamblers when they die with Mycosis. */
        public static final TagKey<EntityType<?>> MYCOSIS_RISERS = tag("mycosis_risers");

        private static TagKey<EntityType<?>> tag(String name) {
            return TagKey.create(Registries.ENTITY_TYPE, SporeAndStem.id(name));
        }
    }

    public static final class Biomes {
        private Biomes() {
        }

        public static TagKey<Biome> tag(String name) {
            return TagKey.create(Registries.BIOME, SporeAndStem.id(name));
        }
    }
}
